import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.wVcpyw2-.js";const b=JSON.parse('{"title":"从零搭建首页（完整案例）","description":"从零搭建首页（完整案例）：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/scenarios/homepage.md","filePath":"features/ui-editor/scenarios/homepage.md","lastUpdated":1785051348000}'),e={name:"features/ui-editor/scenarios/homepage.md"};function n(s,t,l,i,h,g){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="从零搭建首页-完整案例" tabindex="-1">从零搭建首页（完整案例） <a class="header-anchor" href="#从零搭建首页-完整案例" aria-label="Permalink to &quot;从零搭建首页（完整案例）&quot;">​</a></h1><p>本篇用 <strong>真实操作顺序</strong> 带你在 UI 编辑器里搭一个可用的校园首页，每一步都对应管理后台里的具体位置。完成后你将掌握：页面创建、组件添加、属性/样式、筛选联动、保存与启用。</p><p><strong>预计耗时：</strong> 30～60 分钟（含上传图片）</p><hr><h2 id="目标效果" tabindex="-1">目标效果 <a class="header-anchor" href="#目标效果" aria-label="Permalink to &quot;目标效果&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│  透明导航 + 顶部背景图        │</span></span>
<span class="line"><span>├─────────────────────────────┤</span></span>
<span class="line"><span>│  轮播图（3 张活动图）         │</span></span>
<span class="line"><span>│  金刚区（4 列：二手/跑腿/投票/活动）│</span></span>
<span class="line"><span>│  搜索栏（跳转搜索页）         │</span></span>
<span class="line"><span>│  模块标题「热门话题」         │</span></span>
<span class="line"><span>│  话题气泡                     │</span></span>
<span class="line"><span>│  模块标题「最新动态」         │</span></span>
<span class="line"><span>│  筛选标签（推荐/最新/视频）   │</span></span>
<span class="line"><span>│  笔记列表（双列模板）         │</span></span>
<span class="line"><span>│  结束文本「没有更多了」       │</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span></code></pre></div><hr><h2 id="第-0-步-前置条件" tabindex="-1">第 0 步：前置条件 <a class="header-anchor" href="#第-0-步-前置条件" aria-label="Permalink to &quot;第 0 步：前置条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>检查</th></tr></thead><tbody><tr><td>管理后台</td><td>H5 浏览器打开，已登录超级管理员</td></tr><tr><td>UI 模块</td><td><strong>系统设置 → 我的模块</strong> 中 UI 配置已开通</td></tr><tr><td>文件存储</td><td><strong>系统配置 → 文件存储</strong> 已保存且测试通过</td></tr><tr><td>区域</td><td>本案例用 <strong>平台默认</strong>；多校区请先 <a href="/config/region">区域管理</a></td></tr></tbody></table><hr><h2 id="第-1-步-创建首页配置" tabindex="-1">第 1 步：创建首页配置 <a class="header-anchor" href="#第-1-步-创建首页配置" aria-label="Permalink to &quot;第 1 步：创建首页配置&quot;">​</a></h2><ol><li><strong>UI管理 → 页面配置</strong></li><li>顶部区域选 <strong>平台默认</strong></li><li>点 <strong>+ 新建页面</strong></li><li>类型选 <strong>首页</strong>（对应底部 Tab 首页，不是「功能页」）</li><li>页面名称填：<code>平台首页 v1</code></li><li>点 <strong>创建并编辑</strong></li></ol><hr><h2 id="第-2-步-页面级设置-导航与顶图" tabindex="-1">第 2 步：页面级设置（导航与顶图） <a class="header-anchor" href="#第-2-步-页面级设置-导航与顶图" aria-label="Permalink to &quot;第 2 步：页面级设置（导航与顶图）&quot;">​</a></h2><p>进入三栏编辑器后，<strong>点击画布空白处</strong>（不要选中任何组件），右侧出现 <strong>页面配置</strong>。</p><table tabindex="0"><thead><tr><th>配置项</th><th>建议值</th><th>说明</th></tr></thead><tbody><tr><td>页面背景颜色</td><td><code>#F5F5F5</code></td><td>列表区底色</td></tr><tr><td>顶部背景图</td><td>上传一张 750×400 左右头图</td><td>营造沉浸式顶部</td></tr><tr><td>背景图高度</td><td><code>400</code> rpx</td><td>按设计微调</td></tr><tr><td>导航栏样式</td><td><strong>默认</strong> 或 <strong>胶囊</strong></td><td>有顶图时可用透明/胶囊</td></tr><tr><td>显示标题</td><td>开</td><td>—</td></tr><tr><td>页面标题</td><td>留空或填站点名</td><td>留空则用页面名称</td></tr><tr><td>分享标题</td><td><code>欢迎来到 XX 校园</code></td><td>用户分享小程序卡片</td></tr><tr><td>分享图片</td><td>上传 5:4 比例图</td><td>微信分享图</td></tr></tbody></table><hr><h2 id="第-3-步-添加轮播图" tabindex="-1">第 3 步：添加轮播图 <a class="header-anchor" href="#第-3-步-添加轮播图" aria-label="Permalink to &quot;第 3 步：添加轮播图&quot;">​</a></h2><ol><li>左侧 <strong>布局导航 → 轮播图</strong></li><li>右侧 <strong>属性 → 图片列表 → + 添加图片</strong>，上传 3 张 Banner</li><li>每张图配置 <strong>点击动作</strong>（示例）：</li></ol><table tabindex="0"><thead><tr><th>图片</th><th>点击动作</th></tr></thead><tbody><tr><td>图 1</td><td>跳转页面 → 某活动 <strong>自定义页</strong></td></tr><tr><td>图 2</td><td>跳转页面 → 投票列表</td></tr><tr><td>图 3</td><td>无动作 或 外链活动 H5</td></tr></tbody></table><ol start="4"><li><strong>播放</strong> 区：自动播放 <strong>开</strong>，间隔 <code>3000</code> ms，循环 <strong>开</strong></li><li><strong>指示器</strong>：显示，底部居中，激活色 <code>#FFFFFF</code></li><li><strong>样式 Tab</strong>：高度 <code>300</code> rpx，左右 margin 各 <code>24</code> rpx</li></ol><hr><h2 id="第-4-步-金刚区-4-列快捷入口" tabindex="-1">第 4 步：金刚区（4 列快捷入口） <a class="header-anchor" href="#第-4-步-金刚区-4-列快捷入口" aria-label="Permalink to &quot;第 4 步：金刚区（4 列快捷入口）&quot;">​</a></h2><ol><li>添加 <strong>金刚区</strong></li><li><strong>属性</strong>：</li></ol><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>列数</td><td><code>4</code></td></tr><tr><td>图标大小</td><td><code>88</code> rpx</td></tr><tr><td>行间距</td><td><code>24</code> rpx</td></tr></tbody></table><ol start="3"><li>添加 4 个 <strong>items</strong>（示例）：</li></ol><table tabindex="0"><thead><tr><th>文字</th><th>图标/图片</th><th>点击动作</th></tr></thead><tbody><tr><td>二手闲置</td><td>选图标或上传</td><td>跳转 → 闲置列表页</td></tr><tr><td>跑腿</td><td>选图标</td><td>跳转 → 跑腿服务列表</td></tr><tr><td>投票</td><td>选图标</td><td>跳转 → 投票活动</td></tr><tr><td>校园活动</td><td>选图标</td><td>跳转 → 自定义活动页</td></tr></tbody></table><ol start="4"><li><strong>样式 Tab</strong>：marginTop <code>20</code>，paddingBottom <code>16</code></li></ol><hr><h2 id="第-5-步-搜索栏" tabindex="-1">第 5 步：搜索栏 <a class="header-anchor" href="#第-5-步-搜索栏" aria-label="Permalink to &quot;第 5 步：搜索栏&quot;">​</a></h2><ol><li>添加 <strong>搜索栏</strong></li><li>占位符：<code>搜索笔记、圈子、用户</code></li><li><strong>点击动作</strong> → 跳转 <strong>搜索页</strong>（从路由选择器选）</li><li>右侧「搜一搜」按钮可保留或隐藏（按设计）</li><li><strong>样式</strong>：margin 左右 <code>24</code>，marginBottom <code>16</code></li></ol><hr><h2 id="第-6-步-话题模块" tabindex="-1">第 6 步：话题模块 <a class="header-anchor" href="#第-6-步-话题模块" aria-label="Permalink to &quot;第 6 步：话题模块&quot;">​</a></h2><ol><li>添加 <strong>模块标题</strong>：标题 <code>热门话题</code>，开启 <strong>更多</strong>，更多动作 → 热门话题榜</li><li>添加 <strong>话题气泡</strong></li><li>标题栏标题可改为 <code>大家都在聊</code></li><li>气泡样式：圆角 <code>999</code>，背景 <code>#FFFFFF</code>，行间距 <code>16</code></li><li><strong>说明：</strong> 线上话题数据自动拉取，编辑器内为演示布局</li></ol><hr><h2 id="第-7-步-筛选标签-笔记列表-联动" tabindex="-1">第 7 步：筛选标签 + 笔记列表（联动） <a class="header-anchor" href="#第-7-步-筛选标签-笔记列表-联动" aria-label="Permalink to &quot;第 7 步：筛选标签 + 笔记列表（联动）&quot;">​</a></h2><p>这是首页 <strong>最核心</strong> 的一步，须保证 <strong>联动 Key 一致</strong>。</p><h3 id="_7-1-添加筛选标签" tabindex="-1">7.1 添加筛选标签 <a class="header-anchor" href="#_7-1-添加筛选标签" aria-label="Permalink to &quot;7.1 添加筛选标签&quot;">​</a></h3><ol><li><strong>布局导航 → 筛选标签</strong>（全页只能 1 个）</li><li><strong>内容模式</strong> → <strong>API 联动</strong>（不是 Tab 独立内容）</li><li><strong>联动目标</strong> → <strong>笔记</strong></li><li><strong>联动标识</strong> → 填 <code>home-feed</code>（自定义字符串，记住它）</li><li>添加 Tab 项：</li></ol><table tabindex="0"><thead><tr><th>标签名</th><th>笔记排序 note_order_by</th><th>说明</th></tr></thead><tbody><tr><td>推荐</td><td>smart</td><td>默认选中</td></tr><tr><td>最新</td><td>created_desc</td><td>—</td></tr><tr><td>视频</td><td>video</td><td>仅视频笔记</td></tr></tbody></table><ol start="6"><li>吸顶：<strong>开</strong>（滚动时标签栏固定在顶部）</li></ol><h3 id="_7-2-添加笔记列表" tabindex="-1">7.2 添加笔记列表 <a class="header-anchor" href="#_7-2-添加笔记列表" aria-label="Permalink to &quot;7.2 添加笔记列表&quot;">​</a></h3><ol><li><strong>社区内容 → 笔记列表</strong>（与圈子列表/瀑布流 <strong>三选一</strong>）</li><li><strong>联动标识</strong> → 同样填 <code>home-feed</code></li><li><strong>模板选择 uiTemplate</strong>：</li></ol><table tabindex="0"><thead><tr><th>模板</th><th>效果</th></tr></thead><tbody><tr><td>1</td><td>传统双列，信息较全</td></tr><tr><td>2</td><td>带热评条</td></tr><tr><td>3</td><td>一行互动图标</td></tr></tbody></table><p>本案例选 <strong>模板 1</strong>。</p><ol start="4"><li><strong>显示开关</strong>（建议）：</li></ol><table tabindex="0"><thead><tr><th>开关</th><th>建议</th></tr></thead><tbody><tr><td>显示媒体</td><td>开</td></tr><tr><td>显示话题</td><td>开</td></tr><tr><td>显示位置</td><td>开</td></tr><tr><td>显示圈子</td><td>开</td></tr><tr><td>显示认证标识</td><td>开</td></tr></tbody></table><ol start="5"><li><p><strong>样式 Tab</strong></p><ul><li>外边距：列表整体 marginTop <code>16</code></li><li>卡片内边距/圆角：在 <strong>样式</strong> 里调卡片背景 <code>#FFFFFF</code>、圆角 <code>16</code></li></ul></li><li><p>将笔记列表 <strong>移到画布最底部</strong>（用 <strong>下移</strong> 直到最后一个内容组件）</p></li></ol><h3 id="_7-3-添加结束文本" tabindex="-1">7.3 添加结束文本 <a class="header-anchor" href="#_7-3-添加结束文本" aria-label="Permalink to &quot;7.3 添加结束文本&quot;">​</a></h3><ol><li><strong>信息展示 → 结束文本</strong></li><li><strong>作为列表页脚</strong> → <strong>开</strong>（homeListFooter）</li><li>文案：<code>没有更多了</code></li><li>放在笔记列表 <strong>正下方</strong></li></ol><hr><h2 id="第-8-步-预览与保存" tabindex="-1">第 8 步：预览与保存 <a class="header-anchor" href="#第-8-步-预览与保存" aria-label="Permalink to &quot;第 8 步：预览与保存&quot;">​</a></h2><ol><li>工具栏 <strong>预览</strong>：查看截图效果</li><li><strong>保存</strong> → 勾选 <strong>更新封面截图</strong>（列表页缩略图）</li><li>返回 <strong>页面配置列表</strong></li><li>找到 <code>平台首页 v1</code> → 点 <strong>启用</strong>（同区域旧首页会自动禁用）</li></ol><hr><h2 id="第-9-步-配置-tabbar-若尚未配置" tabindex="-1">第 9 步：配置 TabBar（若尚未配置） <a class="header-anchor" href="#第-9-步-配置-tabbar-若尚未配置" aria-label="Permalink to &quot;第 9 步：配置 TabBar（若尚未配置）&quot;">​</a></h2><p><strong>UI管理 → TabBar配置</strong> → 平台默认：</p><table tabindex="0"><thead><tr><th>Tab</th><th>文字</th><th>跳转</th></tr></thead><tbody><tr><td>1</td><td>首页</td><td>首页 Tab 路由</td></tr><tr><td>2</td><td>发现</td><td>功能页 Tab 路由</td></tr><tr><td>…</td><td>…</td><td>…</td></tr></tbody></table><p>保存后，底部第一个 Tab 进入的即是刚启用的 <strong>应用首页</strong> 配置。</p><hr><h2 id="第-10-步-客户端验收" tabindex="-1">第 10 步：客户端验收 <a class="header-anchor" href="#第-10-步-客户端验收" aria-label="Permalink to &quot;第 10 步：客户端验收&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>预期</th></tr></thead><tbody><tr><td>打开 App 首页</td><td>轮播、金刚区、列表正常</td></tr><tr><td>切换筛选 Tab</td><td>列表刷新为不同排序</td></tr><tr><td>下拉刷新</td><td>列表重新加载</td></tr><tr><td>点击金刚区</td><td>进入对应业务页</td></tr><tr><td>分享</td><td>标题与分享图正确</td></tr></tbody></table><p>若不变：确认客户端 <strong>区域</strong> 与编辑区域一致；杀进程重进。</p><hr><h2 id="常见踩坑" tabindex="-1">常见踩坑 <a class="header-anchor" href="#常见踩坑" aria-label="Permalink to &quot;常见踩坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td>筛选切换列表不动</td><td>联动 Key 不一致</td><td>标签与列表都填相同 <code>home-feed</code></td></tr><tr><td>有两个列表</td><td>加了圈子列表又加笔记</td><td>三选一，删掉多余</td></tr><tr><td>保存了但 App 旧样</td><td>未 <strong>启用</strong> 或区域不对</td><td>列表点启用；核对区域</td></tr><tr><td>图片不显示</td><td>存储未配或 URL 非公网</td><td>检查文件存储 Tab</td></tr></tbody></table><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features/ui-editor/page-types">页面类型说明</a></li><li><a href="/features/ui-editor/components-community#笔记列表-xiaoyi-note-list-section">笔记列表组件详解</a></li><li><a href="/features/ui-editor/components-layout#筛选标签">筛选标签详解</a></li><li><a href="/features/ui-editor/tabbar">TabBar 配置</a></li></ul>`,68)])])}const p=d(e,[["render",n]]);export{b as __pageData,p as default};
